import { getAdminParams, type ReactAdminSvgFileItem } from "./admin-params"
import { adminRestFetch } from "./admin-rest-fetch"
import { resourceApiUrl } from "./resource-api-url"

/** Refresh resource heads on opening a picker; existing App pins never follow this catalog. */
export async function refreshSvgAssets(existing: ReactAdminSvgFileItem[], signal?: AbortSignal): Promise<ReactAdminSvgFileItem[]> {
  const params = getAdminParams()
  if (!params.svgRegistryEnabled) return existing
  const managed: ReactAdminSvgFileItem[] = []
  let after = 0
  do {
    const url = new URL(resourceApiUrl(params.apiUrl, "/svg-assets"), window.location.href)
    url.searchParams.set("limit", "200")
    url.searchParams.set("after", String(after))
    const response = await adminRestFetch(url.href, {
      signal, credentials: "same-origin", cache: "no-store", headers: { Accept: "application/json", "X-WP-Nonce": params.nonce },
    })
    const data = await response.json()
    if (!response.ok || !Array.isArray(data?.files)) throw new Error(data?.message ?? "The SVG library could not be loaded.")
    for (const file of data.files) {
      if (!Number.isSafeInteger(file.assetId) || file.assetId <= 0 || !Number.isSafeInteger(file.revisionId) || file.revisionId <= 0
        || typeof file.name !== "string" || typeof file.pathShort !== "string" || typeof file.relativeUrl !== "string" || !file.relativeUrl.startsWith("/") || file.relativeUrl.startsWith("//")) {
        throw new Error("The server returned an invalid SVG resource.")
      }
      managed.push(file)
    }
    if (data.nextAfter == null) break
    if (!Number.isSafeInteger(data.nextAfter) || data.nextAfter <= after) throw new Error("The SVG catalog cursor did not advance.")
    after = data.nextAfter
  } while (!signal?.aborted)
  signal?.throwIfAborted()
  const originals = new Set(managed.map(file => file.originalUrl).filter(Boolean))
  return [...existing.filter(file => !file.assetId && !file.relativeUrl.includes("/svg-registry/") && !originals.has(file.relativeUrl)), ...managed]
}
